const devices = [
    { id: 'light_001', power: 60, factor: 0.001, name: '客厅主灯' },
    { id: 'light_002', power: 40, factor: 0.001, name: '卧室灯' },
    { id: 'light_003', power: 30, factor: 0.001, name: '厨房灯' },
    { id: 'fan_001', power: 75, factor: 0.002, name: '客厅风扇' },
    { id: 'fan_002', power: 60, factor: 0.002, name: '卧室风扇' },
    { id: 'ac_001', power: 1500, factor: 0.01, name: '客厅空调' },
    { id: 'ac_002', power: 1200, factor: 0.01, name: '卧室空调' }
];

let insertValues = [];
let debugMsg = "生成电量数据:\n";

for (const device of devices) {
    const status = flow.get(`device_${device.id}_status`) || 'off';

    debugMsg += `${device.name}: ${status}\n`;

    if (status == 'on') {
        // 生成模拟用电数据（更真实的范围）
        const usage = (device.power * device.factor * (0.3 + Math.random() * 0.4)) / 100;
        insertValues.push(`('${device.id}', ${usage.toFixed(4)})`);
        debugMsg += `  → 用电量: ${usage.toFixed(4)} 度\n`;
    }
}

if (insertValues.length > 0) {
    const sql = `INSERT INTO power_consumption (device_id, power_usage) VALUES ${insertValues.join(', ')}`;
    msg.topic = sql;
    delete msg.payload;
    node.warn(debugMsg);
} else {
    msg.topic = "SELECT 1";
    delete msg.payload;
    node.warn("没有设备开启，不生成电量数据");
}

return msg;

const sql = "UPDATE devices SET status = 'off' WHERE device_id IN ('light_001', 'light_002', 'light_003', 'fan_001', 'fan_002', 'ac_001', 'ac_002')";
msg.topic = sql;
delete msg.payload;
return msg;

// 更新流上下文并触发相关操作
if (msg.topic === 'update_flow_status' && msg.payload) {
    // 更新所有设备状态到流上下文
    msg.payload.forEach(update => {
        flow.set(`device_${update.deviceId}_status`, update.status);
    });

    // 立即触发实时数据查询
    const triggerMsg = {
        topic: 'SELECT 1',  // 触发查询的简单SQL
        trigger: 'immediate'
    };

    // 强制立即执行一次实时查询
    setTimeout(() => {
        node.send([null, triggerMsg]);
    }, 100);

    return [[], triggerMsg];
}

return [null, null];

// 构建实时数据查询SQL，使用topic传递
const sql = `SELECT d.device_id, d.device_name, d.device_type, d.status, 
    CASE 
        WHEN d.status = 'on' THEN COALESCE(SUM(p.power_usage), 0)
        ELSE 0 
    END as total_power 
    FROM devices d 
    LEFT JOIN power_consumption p ON d.device_id = p.device_id 
        AND p.timestamp >= NOW() - INTERVAL 2 MINUTE 
    GROUP BY d.device_id, d.device_name, d.device_type, d.status 
    ORDER BY d.device_type, d.device_name`;

msg.topic = sql;
delete msg.payload;

return msg;

const label = msg.label || msg.topic;

const deviceMap = {
    "客厅主灯": "light_001",
    "卧室灯": "light_002",
    "厨房灯": "light_003",
    "客厅风扇": "fan_001",
    "卧室风扇": "fan_002",
    "客厅空调": "ac_001",
    "卧室空调": "ac_002"
};

const deviceId = deviceMap[label];
if (!deviceId) return [null, null];

const status = msg.payload;
flow.set(`device_${deviceId}_status`, status);

const sql = `UPDATE devices SET status = '${status}', updated_at = NOW() WHERE device_id = '${deviceId}'`;
const sqlMsg = {topic: sql};

const triggerMsg = {
    topic: 'device_control_trigger',
    deviceId: deviceId,
    status: status,
    label: label,
    timestamp: new Date().toISOString()
};

return [sqlMsg, triggerMsg];

if (msg.topic === 'device_control_trigger') {
    flow.set(`device_${msg.deviceId}_status`, msg.status);

    setTimeout(() => {
        const queryMsg = {
            topic: 'trigger_immediate_query',
            deviceId: msg.deviceId,
            status: msg.status
        };
        node.send([null, queryMsg]);
    }, 200);
}

return [];

const actions = {
    'all_on': {
        'light_001': {status: 'on', label: '客厅主灯'},
        'light_002': {status: 'on', label: '卧室灯'},
        'light_003': {status: 'on', label: '厨房灯'},
        'fan_001': {status: 'on', label: '客厅风扇'},
        'fan_002': {status: 'on', label: '卧室风扇'},
        'ac_001': {status: 'on', label: '客厅空调'},
        'ac_002': {status: 'on', label: '卧室空调'}
    },
    'all_off': {
        'light_001': {status: 'off', label: '客厅主灯'},
        'light_002': {status: 'off', label: '卧室灯'},
        'light_003': {status: 'off', label: '厨房灯'},
        'fan_001': {status: 'off', label: '客厅风扇'},
        'fan_002': {status: 'off', label: '卧室风扇'},
        'ac_001': {status: 'off', label: '客厅空调'},
        'ac_002': {status: 'off', label: '卧室空调'}
    },
    'lights_on': {
        'light_001': {status: 'on', label: '客厅主灯'},
        'light_002': {status: 'on', label: '卧室灯'},
        'light_003': {status: 'on', label: '厨房灯'},
        'fan_001': {status: 'off', label: '客厅风扇'},
        'fan_002': {status: 'off', label: '卧室风扇'},
        'ac_001': {status: 'off', label: '客厅空调'},
        'ac_002': {status: 'off', label: '卧室空调'}
    },
    'ac_on': {
        'light_001': {status: 'off', label: '客厅主灯'},
        'light_002': {status: 'off', label: '卧室灯'},
        'light_003': {status: 'off', label: '厨房灯'},
        'fan_001': {status: 'off', label: '客厅风扇'},
        'fan_002': {status: 'off', label: '卧室风扇'},
        'ac_001': {status: 'on', label: '客厅空调'},
        'ac_002': {status: 'on', label: '卧室空调'}
    }
};

const action = actions[msg.payload];
if (!action) return [null, null, null];

let sqlUpdates = [];
let flowUpdates = [];
let uiUpdates = [];

for (const deviceId in action) {
    const deviceInfo = action[deviceId];
    const status = deviceInfo.status;
    const label = deviceInfo.label;

    // 更新流状态
    flow.set(`device_${deviceId}_status`, status);
    flowUpdates.push({deviceId: deviceId, status: status});

    // 生成SQL更新
    sqlUpdates.push(`UPDATE devices SET status = '${status}', updated_at = NOW() WHERE device_id = '${deviceId}'`);

    // 生成UI更新消息
    uiUpdates.push({
        topic: 'ui_update',
        label: label,
        payload: status,
        deviceId: deviceId
    });
}

const sql = sqlUpdates.join('; ');
const sqlMsg = {topic: sql};

const flowMsg = {
    topic: 'update_flow_status',
    payload: flowUpdates
};

// 输出到三个端口：SQL更新、流状态更新、UI开关更新
return [sqlMsg, flowMsg, uiUpdates];

// 如果是数组，处理多个开关更新
if (Array.isArray(msg)) {
    // 将数组中的每个消息单独发送
    for (const uiMsg of msg) {
        node.send([uiMsg]);
    }
    return [];
}

// 如果是单个消息，直接转发
if (msg.topic === 'ui_update') {
    // 延迟一点时间，确保流状态已更新
    setTimeout(() => {
        const syncMsg = {
            topic: msg.topic,
            label: msg.label,
            payload: msg.payload,
            deviceId: msg.deviceId
        };
        node.send([syncMsg]);
    }, 100);
}

return [];

// 统一处理所有MySQL查询结果
if (!msg.payload || !msg.topic) {
    return [null, null];
}

const topic = msg.topic.toString();

// 1. 处理统计查询结果
if (Array.isArray(msg.payload)) {
    // 通过statType识别统计查询
    if (msg.statType) {
        // 统计查询结果，发送到统计处理器
        return [msg, null];
    }

    // 通过topic识别统计表查询
    if (topic.includes('hourly_stats') || topic.includes('FROM hourly_stats') || 
        topic.includes('daily_stats') || topic.includes('FROM daily_stats') ||
        topic.includes('weekly_stats') || topic.includes('FROM weekly_stats') ||
        topic.includes('monthly_stats') || topic.includes('FROM monthly_stats')) {

        // 提取统计类型
        let statType = '';
        if (topic.includes('hourly_stats') || topic.includes('FROM hourly_stats')) {
            statType = 'hourly';
        } else if (topic.includes('daily_stats') || topic.includes('FROM daily_stats')) {
            statType = 'daily';
        } else if (topic.includes('weekly_stats') || topic.includes('FROM weekly_stats')) {
            statType = 'weekly';
        } else if (topic.includes('monthly_stats') || topic.includes('FROM monthly_stats')) {
            statType = 'monthly';
        }

        msg.statType = statType;
        return [msg, null];
    }
}

// 2. 实时数据查询结果
if (topic.includes('SELECT d.device_id')) {
    return [null, msg];
}

// 3. 其他查询结果
return [null, msg];

// 增强的实时数据处理，确保总是显示当前流上下文中的设备状态
let deviceStatus = "<h4>设备实时状态</h4>";
let totalPower = 0;

// 从流上下文读取所有设备状态
const devices = [
    {id: 'light_001', name: '客厅主灯'},
    {id: 'light_002', name: '卧室灯'},
    {id: 'light_003', name: '厨房灯'},
    {id: 'fan_001', name: '客厅风扇'},
    {id: 'fan_002', name: '卧室风扇'},
    {id: 'ac_001', name: '客厅空调'},
    {id: 'ac_002', name: '卧室空调'}
];

// 如果有数据库数据，使用数据库数据；否则使用流上下文状态
if (msg.payload && Array.isArray(msg.payload)) {
    // 使用数据库返回的数据
    for (const row of msg.payload) {
        const power = parseFloat(row.total_power) || 0;
        const status = row.status || 'off';

        if (status === 'on') {
            totalPower += power;
        }

        const statusIcon = status === 'on' ? '●' : '○';
        const statusColor = status === 'on' ? 'green' : 'red';
        const statusText = status === 'on' ? '开启' : '关闭';
        deviceStatus += `<p><span style="color:${statusColor}; font-weight:bold;">${statusIcon}</span> ${row.device_name}: ${statusText} - ${power.toFixed(4)} 度</p>`;
    }
} else {
    // 使用流上下文状态
    for (const device of devices) {
        const status = flow.get(`device_${device.id}_status`) || 'off';
        const power = status === 'on' ? (Math.random() * 0.1).toFixed(4) : 0;

        if (status === 'on') {
            totalPower += parseFloat(power);
        }

        const statusIcon = status === 'on' ? '●' : '○';
        const statusColor = status === 'on' ? 'green' : 'red';
        const statusText = status === 'on' ? '开启' : '关闭';
        deviceStatus += `<p><span style="color:${statusColor}; font-weight:bold;">${statusIcon}</span> ${device.name}: ${statusText} - ${power} 度</p>`;
    }
}

deviceStatus += `<p><strong>总用电量: ${totalPower.toFixed(4)} 度</strong></p>`;

// 更新仪表盘和状态文本
const gaugeMsg = {
    payload: totalPower.toFixed(4)
};

const statusMsg = {
    payload: deviceStatus
};

return [gaugeMsg, statusMsg];

if (msg.topic && msg.topic.includes('小时数据生成完成')) {
    node.send([{topic: '显示消息', payload: msg.topic}]);
}
else if (msg.topic && msg.topic.includes('日数据生成完成')) {
    node.send([{topic: '显示消息', payload: msg.topic}]);
}
else if (msg.topic && msg.topic.includes('周数据生成完成')) {
    node.send([{topic: '显示消息', payload: msg.topic}]);
}
else if (msg.topic && msg.topic.includes('月数据生成完成')) {
    node.send([{topic: '显示消息', payload: msg.topic}]);
}
else if (msg.payload && msg.payload.affectedRows !== undefined) {
    node.send([{topic: '显示消息', payload: `SQL执行成功，影响行数: ${msg.payload.affectedRows}`}]);
}
return [null, null];

const deviceIds = ['light_001', 'light_002', 'light_003', 'fan_001', 'fan_002', 'ac_001', 'ac_002'];
const devicePowers = {
    'light_001': 0.075,
    'light_002': 0.059,
    'light_003': 0.032,
    'fan_001': 0.152,
    'fan_002': 0.121,
    'ac_001': 1.423,
    'ac_002': 1.135
};

const now = new Date();
let sqlQueries = [];

for (let hourOffset = 0; hourOffset < 24; hourOffset++) {
    const hourStart = new Date(now.getTime() - (hourOffset * 60 * 60 * 1000));
    hourStart.setMinutes(0, 0, 0);

    const hourStr = hourStart.toISOString().slice(0, 19).replace('T', ' ');

    deviceIds.forEach(deviceId => {
        const basePower = devicePowers[deviceId];
        const variation = 0.1 + Math.random() * 0.3;
        const totalPower = basePower * variation;
        const avgPower = totalPower / 60;
        const maxPower = avgPower * (1.2 + Math.random() * 0.3);
        const minPower = avgPower * (0.7 + Math.random() * 0.2);
        const recordCount = Math.floor(30 + Math.random() * 30);

        const sql = `INSERT INTO hourly_stats (device_id, hour_start, total_power, avg_power, max_power, min_power, record_count) ` +
                   `VALUES ('${deviceId}', '${hourStr}', ${totalPower.toFixed(4)}, ${avgPower.toFixed(4)}, ${maxPower.toFixed(4)}, ${minPower.toFixed(4)}, ${recordCount}) ` +
                   `ON DUPLICATE KEY UPDATE total_power = VALUES(total_power), avg_power = VALUES(avg_power), max_power = VALUES(max_power), min_power = VALUES(min_power), record_count = VALUES(record_count)`;

        sqlQueries.push(sql);
    });
}

const sql = sqlQueries.join('; ');
msg.topic = sql;
delete msg.payload;

return [msg, {topic: '小时数据生成完成，共生成' + (sqlQueries.length) + '条记录'}];

const deviceIds = ['light_001', 'light_002', 'light_003', 'fan_001', 'fan_002', 'ac_001', 'ac_002'];
const deviceMultipliers = {
    'light_001': 1.0,
    'light_002': 0.8,
    'light_003': 0.6,
    'fan_001': 2.0,
    'fan_002': 1.6,
    'ac_001': 20.0,
    'ac_002': 16.0
};

const now = new Date();
let sqlQueries = [];

for (let dayOffset = 0; dayOffset < 7; dayOffset++) {
    const currentDate = new Date(now.getTime() - (dayOffset * 24 * 60 * 60 * 1000));
    const dateStr = currentDate.toISOString().slice(0, 10);

    deviceIds.forEach(deviceId => {
        const baseMultiplier = deviceMultipliers[deviceId];
        const dailyVariation = 0.7 + Math.random() * 0.6;
        const totalPower = baseMultiplier * dailyVariation;
        const avgPower = totalPower / 1440;
        const maxPower = avgPower * (1.5 + Math.random() * 0.5);
        const minPower = avgPower * (0.5 + Math.random() * 0.3);
        const recordCount = Math.floor(1000 + Math.random() * 500);

        const sql = `INSERT INTO daily_stats (device_id, date, total_power, avg_power, max_power, min_power, record_count) ` +
                   `VALUES ('${deviceId}', '${dateStr}', ${totalPower.toFixed(4)}, ${avgPower.toFixed(4)}, ${maxPower.toFixed(4)}, ${minPower.toFixed(4)}, ${recordCount}) ` +
                   `ON DUPLICATE KEY UPDATE total_power = VALUES(total_power), avg_power = VALUES(avg_power), max_power = VALUES(max_power), min_power = VALUES(min_power), record_count = VALUES(record_count)`;

        sqlQueries.push(sql);
    });
}

const sql = sqlQueries.join('; ');
msg.topic = sql;
delete msg.payload;

return [msg, {topic: '日数据生成完成，共生成' + (sqlQueries.length) + '条记录'}];

const deviceIds = ['light_001', 'light_002', 'light_003', 'fan_001', 'fan_002', 'ac_001', 'ac_002'];
const deviceMultipliers = {
    'light_001': 7.0,
    'light_002': 5.6,
    'light_003': 4.2,
    'fan_001': 14.0,
    'fan_002': 11.2,
    'ac_001': 140.0,
    'ac_002': 112.0
};

const now = new Date();
let sqlQueries = [];

for (let weekOffset = 0; weekOffset < 8; weekOffset++) {
    const weekStartDate = new Date(now.getTime() - (weekOffset * 7 * 24 * 60 * 60 * 1000));
    const weekStart = weekStartDate.toISOString().slice(0, 10);
    const weekNumber = getWeekNumber(weekStartDate);

    deviceIds.forEach(deviceId => {
        const baseMultiplier = deviceMultipliers[deviceId];
        const weeklyVariation = 0.6 + Math.random() * 0.8;
        const totalPower = baseMultiplier * weeklyVariation;
        const avgPower = totalPower / (7 * 1440);
        const maxPower = avgPower * (1.8 + Math.random() * 0.7);
        const minPower = avgPower * (0.4 + Math.random() * 0.4);
        const recordCount = Math.floor(7000 + Math.random() * 3000);

        const sql = `INSERT INTO weekly_stats (device_id, week_start, week_number, total_power, avg_power, max_power, min_power, record_count) ` +
                   `VALUES ('${deviceId}', '${weekStart}', ${weekNumber}, ${totalPower.toFixed(4)}, ${avgPower.toFixed(4)}, ${maxPower.toFixed(4)}, ${minPower.toFixed(4)}, ${recordCount}) ` +
                   `ON DUPLICATE KEY UPDATE total_power = VALUES(total_power), avg_power = VALUES(avg_power), max_power = VALUES(max_power), min_power = VALUES(min_power), record_count = VALUES(record_count)`;

        sqlQueries.push(sql);
    });
}

const sql = sqlQueries.join('; ');
msg.topic = sql;
delete msg.payload;

function getWeekNumber(date) {
    const firstDayOfYear = new Date(date.getFullYear(), 0, 1);
    const pastDaysOfYear = (date - firstDayOfYear) / 86400000;
    return Math.ceil((pastDaysOfYear + firstDayOfYear.getDay() + 1) / 7);
}

return [msg, {topic: '周数据生成完成，共生成' + (sqlQueries.length) + '条记录'}];

const deviceIds = ['light_001', 'light_002', 'light_003', 'fan_001', 'fan_002', 'ac_001', 'ac_002'];
const deviceMultipliers = {
    'light_001': 30.0,
    'light_002': 24.0,
    'light_003': 18.0,
    'fan_001': 60.0,
    'fan_002': 48.0,
    'ac_001': 600.0,
    'ac_002': 480.0
};

const now = new Date();
let sqlQueries = [];

for (let monthOffset = 0; monthOffset < 6; monthOffset++) {
    const monthDate = new Date(now.getFullYear(), now.getMonth() - monthOffset, 1);
    const monthStart = monthDate.toISOString().slice(0, 10);
    const monthNumber = monthDate.getMonth() + 1;

    deviceIds.forEach(deviceId => {
        const baseMultiplier = deviceMultipliers[deviceId];
        const monthlyVariation = 0.5 + Math.random() * 1.0;
        const totalPower = baseMultiplier * monthlyVariation;
        const avgPower = totalPower / (30 * 1440);
        const maxPower = avgPower * (2.0 + Math.random() * 1.0);
        const minPower = avgPower * (0.3 + Math.random() * 0.4);
        const recordCount = Math.floor(30000 + Math.random() * 15000);

        const sql = `INSERT INTO monthly_stats (device_id, month_start, month_number, total_power, avg_power, max_power, min_power, record_count) ` +
                   `VALUES ('${deviceId}', '${monthStart}', ${monthNumber}, ${totalPower.toFixed(4)}, ${avgPower.toFixed(4)}, ${maxPower.toFixed(4)}, ${minPower.toFixed(4)}, ${recordCount}) ` +
                   `ON DUPLICATE KEY UPDATE total_power = VALUES(total_power), avg_power = VALUES(avg_power), max_power = VALUES(max_power), min_power = VALUES(min_power), record_count = VALUES(record_count)`;

        sqlQueries.push(sql);
    });
}

const sql = sqlQueries.join('; ');
msg.topic = sql;
delete msg.payload;

return [msg, {topic: '月数据生成完成，共生成' + (sqlQueries.length) + '条记录'}];

const now = new Date();
const delay = 1000;

setTimeout(() => {
    node.send([{topic: 'generate_hourly'}]);
}, delay);

setTimeout(() => {
    node.send([{topic: 'generate_daily'}]);
}, delay * 2);

setTimeout(() => {
    node.send([{topic: 'generate_weekly'}]);
}, delay * 3);

setTimeout(() => {
    node.send([{topic: 'generate_monthly'}]);
}, delay * 4);

return [{topic: '开始一键生成所有统计数据...'}];

const sql = `TRUNCATE TABLE hourly_stats; TRUNCATE TABLE daily_stats; TRUNCATE TABLE weekly_stats; TRUNCATE TABLE monthly_stats;`;
msg.topic = sql;
delete msg.payload;

return [msg, {topic: '统计表数据已清空'}];

const statType = msg.payload;
let querySql = "";
let chartType = "line";
let chartLabel = "用电统计";
let xformat = "HH:mm";

switch(statType) {
    case 'hourly':
        querySql = "SELECT h.device_id, h.hour_start, h.total_power, h.avg_power, h.max_power, h.min_power, h.record_count, d.device_name FROM hourly_stats h JOIN devices d ON h.device_id = d.device_id WHERE h.hour_start >= DATE_SUB(NOW(), INTERVAL 24 HOUR) ORDER BY h.hour_start, d.device_name LIMIT 100";
        chartType = "line";
        chartLabel = "小时用电统计";
        xformat = "HH:mm";
        break;
    case 'daily':
        querySql = "SELECT d_s.device_id, d_s.date, d_s.total_power, d_s.avg_power, d_s.max_power, d_s.min_power, d_s.record_count, d.device_name FROM daily_stats d_s JOIN devices d ON d_s.device_id = d.device_id WHERE d_s.date >= DATE_SUB(NOW(), INTERVAL 30 DAY) ORDER BY d_s.date, d.device_name LIMIT 100";
        chartType = "bar";
        chartLabel = "日用电统计";
        xformat = "MM-DD";
        break;
    case 'weekly':
        querySql = "SELECT w.device_id, w.week_start, w.week_number, w.total_power, w.avg_power, w.max_power, w.min_power, w.record_count, d.device_name FROM weekly_stats w JOIN devices d ON w.device_id = d.device_id WHERE w.week_start >= DATE_SUB(NOW(), INTERVAL 12 WEEK) ORDER BY w.week_start, d.device_name LIMIT 100";
        chartType = "bar";
        chartLabel = "周用电统计";
        xformat = "第W周";
        break;
    case 'monthly':
        querySql = "SELECT m.device_id, m.month_start, m.month_number, m.total_power, m.avg_power, m.max_power, m.min_power, m.record_count, d.device_name FROM monthly_stats m JOIN devices d ON m.device_id = d.device_id WHERE m.month_start >= DATE_SUB(NOW(), INTERVAL 12 MONTH) ORDER BY m.month_start, d.device_name LIMIT 100";
        chartType = "bar";
        chartLabel = "月用电统计";
        xformat = "YYYY-MM";
        break;
    default:
        return [null, null];
}

const queryMsg = { 
    topic: querySql,
    statType: statType,
    chartType: chartType,
    chartLabel: chartLabel,
    xformat: xformat
};

